CheckArrVarAlt[3] = "총자본금";
CheckArrVar[4] = "bzProftAmt";
CheckArrVarAlt[4] = "영업이익금액";
CheckArrVar[5] = "ordnincmAmt";
CheckArrVarAlt[5] = "경상이익금액";
CheckArrVar[6] = "netincmAmt";
CheckArrVarAlt[6] = "당기순이익금액";
CheckArrVar[7] = "bzActivCashFlowAmt";
CheckArrVarAlt[7] = "영업활동현금흐름금액";
CheckArrVar[8] = "fbzNetcap";
CheckArrVarAlt[8] = "영업용순자본금";
CheckArrVar[9] = "totRiskAmt";
CheckArrVarAlt[9] = "총위험금액";
CheckArrVar[10] = "reqPersisPrincCapVal";
CheckArrVarAlt[10] = "필요유지자기자본";
CheckArrVar[11] = "eqtycap";
CheckArrVarAlt[11] = "자기자본금";
CheckArrVar[12] = "otcDrvfncTrdTotRiskAmt";
CheckArrVarAlt[12] = "장외파생금융상품거래총위험금액";
/**
 * @method
 * @name fn_CommaValueAll
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CommaValueAll = function() {
    for (var i = 0; i < 3; i++) {
        fn_ObjValueSetComma(form["totAsstAmt"][i]); // 총자산금액                                        
        fn_ObjValueSetComma(form["cap"][i]); // 자본금                                          
        fn_ObjValueSetComma(form["totDebtAmt"][i]); // 총부채금액                                        
        fn_ObjValueSetComma(form["totCap"][i]); // 총자본금                                          
        fn_ObjValueSetComma(form["bzProftAmt"][i]); // 영업이익금액                                      
        fn_ObjValueSetComma(form["ordnincmAmt"][i]); // 경상이익금액                                      
        fn_ObjValueSetComma(form["netincmAmt"][i]); // 당기순이익금액                                    
        fn_ObjValueSetComma(form["bzActivCashFlowAmt"][i]); // 영업활동현금흐름금액                              
        fn_ObjValueSetComma(form["fbzNetcap"][i]); // 영업용순자본금                                    
        fn_ObjValueSetComma(form["totRiskAmt"][i]); // 총위험금액 
        fn_ObjValueSetComma(form["reqPersisPrincCapVal"][i]); // 필요유지자기자본
        fn_ObjValueSetComma(form["netRto"][i]); // 순자본비율

        fn_ObjValueSetComma(form["eqtycap"][i]); // 자기자본금                                        
        fn_ObjValueSetComma(form["otcDrvfncTrdTotRiskAmt"][i]); // 장외파생금융상품거래총위험금액                    

    }
};
/**
 * @method
 * @name fn_RmCommaValueAll
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_RmCommaValueAll = function() {
    for (var i = 0; i < 3; i++) {
        fn_ObjValueResetRmComma(form["totAsstAmt"][i]); // 총자산금액                                        
        fn_ObjValueResetRmComma(form["cap"][i]); // 자본금                                          
        fn_ObjValueResetRmComma(form["totDebtAmt"][i]); // 총부채금액                                        
