        fn_ObjValueResetRmComma(form["netincmAmt"][i]); // 당기순이익금액                                    
        fn_ObjValueResetRmComma(form["bzActivCashFlowAmt"][i]); // 영업활동현금흐름금액                              
        fn_ObjValueResetRmComma(form["fbzNetcap"][i]); // 영업용순자본금                                    
